// The hand-written layer over the generated schema (docs/adr/0089).
// `lib/database.types.ts` is generated by `bun run db:types` and never edited;
// every override of what the generator emits lives here.
import type { UnstableGetResult } from "@supabase/postgrest-js";
import type { z } from "zod";
import type { Database as Generated } from "@/lib/database.types";
import type { FailurePatternSchema } from "@/lib/schemas/domain";

type GenPublic = Generated["public"];
type GenTables = GenPublic["Tables"];
type GenFunctions = GenPublic["Functions"];

/**
 * Narrows columns of one generated table. `C` may only name columns the table
 * has, so a renamed or dropped column fails here instead of silently widening.
 */
export type Narrow<
	T extends keyof GenTables,
	C extends Partial<Record<keyof GenTables[T]["Row"], unknown>>,
> = Omit<GenTables[T], "Row" | "Insert" | "Update"> & {
	Row: Omit<GenTables[T]["Row"], keyof C> & C;
	Insert: Omit<GenTables[T]["Insert"], keyof C> & { [K in keyof C]?: C[K] };
	Update: Omit<GenTables[T]["Update"], keyof C> & { [K in keyof C]?: C[K] };
};

/**
 * The generator types every RPC argument and return as non-null. `A` lists the
 * arguments that accept null; `NullableReturn` whether the return can be null.
 */
export type NullableArgs<
	F extends keyof GenFunctions,
	A extends keyof GenFunctions[F]["Args"],
	NullableReturn extends boolean = false,
> = {
	Args: Omit<GenFunctions[F]["Args"], A> & {
		[K in A]: GenFunctions[F]["Args"][K] | null;
	};
	Returns: NullableReturn extends true
		? GenFunctions[F]["Returns"] | null
		: GenFunctions[F]["Returns"];
};

type FailurePattern = z.infer<typeof FailurePatternSchema>;

type Tables = Omit<GenTables, "stewardship_domains"> & {
	stewardship_domains: Narrow<"stewardship_domains", { failure_patterns: FailurePattern[] }>;
};

type Functions = Omit<
	GenFunctions,
	"complete_recurring_task" | "skip_recurring_task" | "untick_recurring_snapshot"
> & {
	complete_recurring_task: NullableArgs<
		"complete_recurring_task",
		"p_observed_due" | "p_next_due" | "p_next_recurrence_day" | "p_snapshot_id",
		true
	>;
	skip_recurring_task: NullableArgs<
		"skip_recurring_task",
		"p_observed_due" | "p_next_due" | "p_next_recurrence_day",
		true
	>;
	untick_recurring_snapshot: NullableArgs<"untick_recurring_snapshot", never, true>;
};

type ClientOptions = { PostgrestVersion: "13" };

export type Database = {
	// Local `supabase gen types` omits this; the hosted generator emits it.
	__InternalSupabase: ClientOptions;
	public: Omit<GenPublic, "Tables" | "Functions"> & { Tables: Tables; Functions: Functions };
};

type Schema = Database["public"];

export type TableName = keyof Schema["Tables"];

/**
 * The row type a literal select string yields. A bad column makes the whole
 * row `never`, so the mistake fails at the first use.
 */
export type Selected<T extends TableName, Q extends string> =
	UnstableGetResult<
		Schema,
		Schema["Tables"][T]["Row"],
		T,
		Schema["Tables"][T]["Relationships"],
		Q,
		ClientOptions
	> extends infer R
		? R extends { error: true }
			? never
			: R
		: never;
